import { test, describe } from "node:test";
import assert from "node:assert/strict";

import ExcelJS from "exceljs";

import {
  buildReportWorkbook,
  coerceCell,
  exportFilename,
  sanitizeBrandingLogo,
  type ReportExportSpec,
} from "../src/lib/reporting/excel-export.ts";

/**
 * Execution 60, Section 6 — the branded export is verified by RE-OPENING the
 * generated bytes, not by asserting on the spec. A workbook that cannot be
 * parsed, loses its numbers, or drops the totals is a failed export even if the
 * code that produced it "ran".
 */

async function reopen(buffer: Buffer): Promise<ExcelJS.Workbook> {
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer as unknown as ArrayBuffer);
  return wb;
}

const spec = (over: Partial<ReportExportSpec> = {}): ReportExportSpec => ({
  titleAr: "تقرير المبيعات",
  titleEn: "Sales Report",
  periodLabel: "2026-01-01 — 2026-03-31",
  rtl: false,
  columns: [
    { key: "invoice_number", labelAr: "رقم الفاتورة", labelEn: "Invoice", type: "text", width: 20 },
    { key: "customer", labelAr: "العميل", labelEn: "Customer", type: "text", width: 30 },
    { key: "date", labelAr: "التاريخ", labelEn: "Date", type: "date" },
    { key: "total", labelAr: "الإجمالي", labelEn: "Total", type: "currency" },
  ],
  rows: [
    { invoice_number: "SI-1", customer: "Ahmed", date: "2026-01-15", total: 110 },
    { invoice_number: "SI-2", customer: "Sara", date: "2026-02-20", total: 220 },
    { invoice_number: "SI-3", customer: "Omar", date: "2026-03-05", total: 330 },
  ],
  totals: [{ labelAr: "الإجمالي", labelEn: "Total", columnKey: "total", value: 660 }],
  ...over,
});

describe("Exec 60 — branded report export (LTR)", () => {
  test("produces a parseable workbook whose values survive the round trip", async () => {
    const buf = await buildReportWorkbook(spec());
    const wb = await reopen(buf);
    const sheet = wb.worksheets[0];
    assert.ok(sheet, "a sheet must exist");

    const values: unknown[] = [];
    sheet.eachRow((row) => row.eachCell((cell) => values.push(cell.value)));
    assert.ok(values.includes("SI-1"), "the first invoice number must be present");
    assert.ok(values.includes("Omar"), "the last row must be present");

    // The numbers must be numbers (so Excel can sum them), not strings.
    let sawNumericTotal = false;
    sheet.eachRow((row) => {
      row.eachCell((cell) => {
        if (typeof cell.value === "number" && cell.value === 110) sawNumericTotal = true;
      });
    });
    assert.ok(sawNumericTotal, "amounts must be written as numbers");
  });

  test("the totals row carries a real SUM formula, not a hardcoded number", async () => {
    const buf = await buildReportWorkbook(spec());
    const wb = await reopen(buf);
    const sheet = wb.worksheets[0];
    let formula: string | null = null;
    sheet.eachRow((row) => {
      row.eachCell((cell) => {
        const v = cell.value as { formula?: string } | null;
        if (v && typeof v === "object" && typeof v.formula === "string") formula = v.formula;
      });
    });
    assert.ok(formula, "a SUM formula must be present");
    assert.match(formula!, /^SUM\(D\d+:D\d+\)$/, `the formula must sum the data column, got ${formula}`);
  });

  test("headers use the requested language and the period is on the sheet", async () => {
    const buf = await buildReportWorkbook(spec());
    const wb = await reopen(buf);
    const sheet = wb.worksheets[0];
    const flat: string[] = [];
    sheet.eachRow((row) => row.eachCell((cell) => { if (typeof cell.value === "string") flat.push(cell.value); }));
    assert.ok(flat.includes("Invoice"), "English headers when rtl=false");
    assert.ok(flat.some((s) => s.includes("2026-01-01")), "the period label must be shown");
  });
});

describe("Exec 60 — branded report export (RTL / Arabic)", () => {
  test("an RTL export is right-to-left, Arabic-headed and named in Arabic", async () => {
    const buf = await buildReportWorkbook(spec({ rtl: true }));
    const wb = await reopen(buf);
    const sheet = wb.worksheets[0];
    assert.equal(sheet.views[0].rightToLeft, true, "the sheet must be RTL");
    assert.equal(sheet.name, "تقرير المبيعات");

    const flat: string[] = [];
    sheet.eachRow((row) => row.eachCell((cell) => { if (typeof cell.value === "string") flat.push(cell.value); }));
    assert.ok(flat.includes("رقم الفاتورة"), "Arabic headers when rtl=true");
  });
});

describe("Exec 60 — branding", () => {
  test("the company name and CR appear in the title block", async () => {
    const buf = await buildReportWorkbook(spec({
      branding: { nameEn: "Harbour Consultancies", crNumber: "12345", phone: "+973 17000000" },
    }));
    const wb = await reopen(buf);
    const sheet = wb.worksheets[0];
    const flat: string[] = [];
    sheet.eachRow((row) => row.eachCell((cell) => { if (typeof cell.value === "string") flat.push(cell.value); }));
    assert.ok(flat.includes("Harbour Consultancies"), "brand name must be the title");
    assert.ok(flat.some((s) => s.includes("12345")), "the CR must be shown");
  });

  test("only http(s)/data logos are embedded; anything else is refused", () => {
    assert.equal(sanitizeBrandingLogo("https://cdn.example.com/logo.png"), "https://cdn.example.com/logo.png");
    assert.equal(sanitizeBrandingLogo("data:image/png;base64,AAAA"), "data:image/png;base64,AAAA");
    assert.equal(sanitizeBrandingLogo("javascript:alert(1)"), null);
    assert.equal(sanitizeBrandingLogo("file:///etc/passwd"), null);
    assert.equal(sanitizeBrandingLogo(""), null);
    assert.equal(sanitizeBrandingLogo(null), null);
  });

  test("an unreachable logo does not fail the export", async () => {
    const buf = await buildReportWorkbook(spec({ branding: { nameEn: "X", logoUrl: "https://127.0.0.1:1/nope.png" } }));
    const wb = await reopen(buf);
    assert.ok(wb.worksheets[0], "the workbook must still be produced");
  });
});

describe("Exec 60 — export edge cases", () => {
  test("an empty result set still produces a valid workbook with headers", async () => {
    const buf = await buildReportWorkbook(spec({ rows: [] }));
    const wb = await reopen(buf);
    const sheet = wb.worksheets[0];
    assert.ok(sheet);
    const flat: string[] = [];
    sheet.eachRow((row) => row.eachCell((cell) => { if (typeof cell.value === "string") flat.push(cell.value); }));
    assert.ok(flat.includes("Invoice"), "headers remain for an empty report");
  });

  test("a null/blank cell becomes empty, not the string 'null'", () => {
    assert.equal(coerceCell(null, "text"), null);
    assert.equal(coerceCell(undefined, "text"), null);
    assert.equal(coerceCell("", "currency"), null);
    assert.equal(coerceCell("12.5", "currency"), 12.5);
    assert.equal(coerceCell("abc", "number"), 0);
  });

  test("the filename is filesystem-safe and keeps the period", () => {
    assert.equal(exportFilename("Sales Report", "2026-01-01 — 2026-03-31"), "Sales_Report_2026-01-01_2026-03-31");
    assert.equal(exportFilename("تقرير المبيعات", null), "تقرير_المبيعات");
    assert.ok(!exportFilename("a/b\\c:d", null).includes("/"));
  });
});
